pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Admissible domain: exclude the all-zero selector, which neither version claims.
        vm.assume(interfaceId != bytes4(0x00000000));
        bool expected = interfaceId == 0xd9b67a26 || // IERC1155
                        interfaceId == 0x0e89341c || // IERC1155MetadataURI
                        interfaceId == 0x01ffc9a7;   // IERC165 (via super.supportsInterface)
        assertTrue(c.supportsInterface(interfaceId) == expected);
    }
}
